spec.query:
histogram_quantile(
  0.95,
  sum by (le, deployment_environment_name, service_namespace, service_name) (
    rate(
      http_server_request_duration_seconds_bucket{
        deployment_environment_name=~"$deployment_environment_name",
        service_namespace=~"$service_namespace",
        service_name="$service_name"
      }[$__rate_interval]
    )
  )
)

avg by (deployment_environment_name, service_namespace, service_name) (
  rate(
    http_server_request_duration_seconds_sum{
      deployment_environment_name=~"$deployment_environment_name",
      service_namespace=~"$service_namespace",
      service_name="$service_name"
    }[$__rate_interval]
  )
)
/
avg by (deployment_environment_name, service_namespace, service_name) (
  rate(
    http_server_request_duration_seconds_count{
      deployment_environment_name=~"$deployment_environment_name",
      service_namespace=~"$service_namespace",
      service_name="$service_name"
    }[$__rate_interval]
  )
)

histogram_quantile(
  0.95,
  sum by (le, deployment_environment_name, service_namespace, service_name) (
    rate(
      rpc_server_duration_milliseconds_bucket{
        deployment_environment_name=~"$deployment_environment_name",
        service_namespace=~"$service_namespace",
        service_name="$service_name"
      }[$__rate_interval]
    ) / 1000
  )
)

avg by (deployment_environment_name, service_namespace, service_name) (
  rate(
    rpc_server_duration_milliseconds_sum{
      deployment_environment_name=~"$deployment_environment_name",
      service_namespace=~"$service_namespace",
      service_name="$service_name"
    }[$__rate_interval]
  ) / 1000
)
/
avg by (deployment_environment_name, service_namespace, service_name) (
  rate(
    rpc_server_duration_milliseconds_count{
      deployment_environment_name=~"$deployment_environment_name",
      service_namespace=~"$service_namespace",
      service_name="$service_name"
    }[$__rate_interval]
  )
)

sum by (service_instance_id_host_name) (
  label_join(
    (
      sum by (service_instance_id, host_name) (
         rate(system_cpu_time_seconds_total{job="", state!="idle"}[$__rate_interval])
      )
      * on(host_name) group_left(service_instance_id)
      target_info{service_name="${service_name}"}
    ),
    "service_instance_id_host_name",
    " / ",
    "service_instance_id",
    "host_name"
  )
)

sum by (service_instance_id_host_name) (
  label_join(
    (
      (
        sum by (service_instance_id, host_name) (
          system_memory_usage_bytes{job="", state!="free"}
        )
        /
        sum by (service_instance_id, host_name) (
          system_memory_usage_bytes{job=""}
        )
      )
      * on(host_name) group_left(service_instance_id) (
        target_info{service_name="${service_name}"}
      )
    ),
    "service_instance_id_host_name",
    " / ",
    "service_instance_id",
    "host_name"
  )
)
